import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Sconto","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/n_matematica-finanziaria-ed-attuariale/nb/nbca.md","filePath":"lezioni/n_matematica-finanziaria-ed-attuariale/nb/nbca.md"}`),a={name:`lezioni/n_matematica-finanziaria-ed-attuariale/nb/nbca.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="sconto" tabindex="-1">Sconto <a class="header-anchor" href="#sconto" aria-label="Permalink to “Sconto”">​</a></h1><p>Chiameremo <strong>sconto</strong> il compenso che spetta a chi anticipa un pagamento: questo può avvenire:</p><ul><li>Se il debitore è disposto ad anticipare il pagamento del suo debito (riscattare)</li><li>Se una terza persona (ad esempio una banca) anticipa al creditore l&#39;importo che poi si farà rimborsare dal debitore alla scadenza. Si dice che il credito viene ceduto dal debitore ad un terzo</li></ul><p>Chiunque paghi il debito prima della scadenza vuole un compenso chiamato sconto, sconto si chiama anche l&#39;operazione di cessione del credito si dice pure che il credito viene scontato</p><p>Chiameremo <strong>valore nominale</strong> il valore del credito <strong>somma scontata</strong> il valore nominale diminuito dello sconto</p><p>In pratica la somma scontata è il prezzo di riscatto (vendita) del credito e siccome la somma scontata si riceve subito allora si chiamerà anche <strong>valore attuale</strong></p><blockquote><p><strong>Esempio:</strong> Devo pagare fra <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>2</mn></mrow><annotation encoding="application/x-tex">2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span> anni un importo di <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>10000</mn><mtext>\xA0€</mtext></mrow><annotation encoding="application/x-tex">10000\\text{ €}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">10000</span><span class="mord text"><span class="mord">\xA0€</span></span></span></span></span>. Riscatto ora il mio debito con <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>9500</mn><mtext>\xA0€</mtext></mrow><annotation encoding="application/x-tex">9500\\text{ €}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">9500</span><span class="mord text"><span class="mord">\xA0€</span></span></span></span></span>. <strong><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>10000</mn><mtext>\xA0€</mtext></mrow><annotation encoding="application/x-tex">10000\\text{ €}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">10000</span><span class="mord text"><span class="mord">\xA0€</span></span></span></span></span> valore nominale</strong><strong><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>9500</mn><mtext>\xA0€</mtext></mrow><annotation encoding="application/x-tex">9500\\text{ €}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">9500</span><span class="mord text"><span class="mord">\xA0€</span></span></span></span></span> somma scontata o valore attuale del credito</strong></p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mn>10000</mn><mtext>\xA0€</mtext><mo>−</mo><mn>9500</mn><mtext>\xA0€</mtext><mo>=</mo><mn>500</mn><mtext>\xA0€</mtext></mrow><annotation encoding="application/x-tex">10000\\text{ €} - 9500\\text{ €} = 500\\text{ €} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">10000</span><span class="mord text"><span class="mord">\xA0€</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">9500</span><span class="mord text"><span class="mord">\xA0€</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">500</span><span class="mord text"><span class="mord">\xA0€</span></span></span></span></span></span></p><p>sconto</p></blockquote>`,7)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};